/usr/bin/bash -lc "PYTHONPATH=source python - <<'PY'
import numpy as np,xarray as xr
from xrspatial.reproject import reproject
vals=np.array([[1.,2.,3.],[4.,5.,6.]])
for dims,coords,data in [
 (('y','x'),{'y':[1.5,.5],'x':[2.5,1.5,.5]},vals),
 (('x','y'),{'y':[1.5,.5],'x':[.5,1.5,2.5]},vals.T),
]:
 a=xr.DataArray(data,dims=dims,coords=coords,attrs={'crs':'EPSG:3857'})
 try:
  o=reproject(a,'EPSG:3857',bounds=(0,0,3,2),resolution=1,resampling='nearest',nodata=-9,transform_precision=0)
  print(dims, o.dims, o.values)
 except Exception as e: print(dims,type(e).__name__,e)

# Integer/default nodata behavior outside footprint.
a=xr.DataArray(np.array([[1,2],[3,4]],dtype=np.uint8),dims=('y','x'),coords={'y':[1.5,.5],'x':[.5,1.5]},attrs={'crs':'EPSG:3857'})
for nd in [None,-1,255]:
 try:
  kw={} if nd is None else {'nodata':nd}
  o=reproject(a,'EPSG:3857',bounds=(-1,0,2,2),resolution=1,resampling='nearest',transform_precision=0,**kw)
  print('nd',nd,'dtype',o.dtype,'attr',o.attrs['nodata'],'values',o.values)
 except Exception as e: print('nd',nd,type(e).__name__,e)
PY"
